{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Tasimelteon, the closest analogue, has an absolute oral bioavailability of about 38% in humans, which would support high bioavailability; however, its cyclopropane-containing core differs from the query's fused saturated tricyclic dihydrobenzofuran system, limiting direct transfer of this high-F result.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Darifenacin, which contains the same dihydrobenzofuran-ethyl substructure as the query, has an absolute oral bioavailability of about 15–19% in humans, indicating that this scaffold can undergo extensive first-pass metabolism and yield F below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "MK-458, a fused chiral ether-containing tricyclic analogue, has an absolute oral bioavailability of approximately 5% in humans, demonstrating that rigid fused oxygen-containing ring systems similar to the query can have very low oral bioavailability due to first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Eliglustat, a moderately lipophilic amide-containing drug, has an absolute oral bioavailability of about 8.6% in a PBPK simulation, providing additional affirmative evidence that favorable physicochemical properties do not guarantee F ≥ 20% when first-pass metabolism is extensive.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the closest analogue tasimelteon shows ~38% bioavailability, the query's fused saturated tricyclic dihydrobenzofuran core is more consistent with low-bioavailability scaffolds such as darifenacin (15–19%) and MK-458 (~5%), which undergo extensive first-pass metabolism. The physicochemical prior favoring high F is therefore outweighed by affirmative low-F experimental evidence from structurally relevant analogues.",
  "evidence_gaps": [
    "No direct experimental absolute bioavailability record for the query molecule itself is present in the evidence set.",
    "The closest analogue (tasimelteon) has the opposite outcome, and its structural difference (cyclopropane vs fused saturated tricyclic core) limits transferability.",
    "Low-F supporting analogues have relatively low Morgan similarity to the query, increasing uncertainty in quantitative transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

